// src/features/Sales/pages/SalesPage.jsx
import React, { useState } from 'react';
import {
  Container,
  Typography,
  Divider,
  Box,
  Grid,
  Paper,
  Card,
  CardContent,
  CardActionArea,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import AddIcon from '@mui/icons-material/Add';
import PointOfSaleIcon from '@mui/icons-material/PointOfSale';
import ShoppingCartIcon from '@mui/icons-material/ShoppingCart';
import InventoryIcon from '@mui/icons-material/Inventory';
import AccountBalanceWalletIcon from '@mui/icons-material/AccountBalanceWallet';
import ReceiptIcon from '@mui/icons-material/Receipt';

// Función local para formatear moneda
const formatCurrency = (value) => {
  return new Intl.NumberFormat('es-MX', {
    style: 'currency',
    currency: 'MXN'
  }).format(value || 0);
};

// Función local para formatear fecha
const formatDate = (dateString) => {
  const date = new Date(dateString);
  return date.toLocaleDateString('es-MX', {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  });
};

const SalesPage = () => {
  const navigate = useNavigate();
  
  // Datos de ejemplo para el dashboard
  const dashboardData = {
    totalSales: 25000,
    pendingPayments: 5000,
    inventory: 15000,
    cashFlow: 8000
  };
  
  // Datos de ejemplo para ventas recientes
  const recentSales = [
    { id: 1, date: '2023-05-20', customer: 'Cliente A', total: 1500, status: 'Completada' },
    { id: 2, date: '2023-05-19', customer: 'Cliente B', total: 2300, status: 'Pendiente' },
    { id: 3, date: '2023-05-18', customer: 'Cliente C', total: 980, status: 'Completada' },
    { id: 4, date: '2023-05-17', customer: 'Cliente D', total: 3200, status: 'Cancelada' }
  ];
  
  const getStatusColor = (status) => {
    switch (status) {
      case 'Completada':
        return 'success';
      case 'Pendiente':
        return 'warning';
      case 'Cancelada':
        return 'error';
      default:
        return 'default';
    }
  };
  
  const handleNavigate = (path) => {
    navigate(`/ventas/${path}`);
  };
  
  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h4">
          Gestión de Ventas
        </Typography>
        
        <Button
          variant="contained"
          color="primary"
          startIcon={<AddIcon />}
        >
          Nueva Venta
        </Button>
      </Box>
      
      <Divider sx={{ mb: 4 }} />
      
      {/* Dashboard Cards */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={3}>
          <Paper sx={{ p: 2, display: 'flex', flexDirection: 'column', height: 140 }}>
            <Typography variant="h6" color="text.secondary" gutterBottom>
              Ventas Totales
            </Typography>
            <Typography component="p" variant="h4" sx={{ flexGrow: 1 }}>
              {formatCurrency(dashboardData.totalSales)}
            </Typography>
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <PointOfSaleIcon color="primary" sx={{ mr: 1 }} />
              <Typography variant="body2" color="text.secondary">
                Este mes
              </Typography>
            </Box>
          </Paper>
        </Grid>
        
        <Grid item xs={12} sm={6} md={3}>
          <Paper sx={{ p: 2, display: 'flex', flexDirection: 'column', height: 140 }}>
            <Typography variant="h6" color="text.secondary" gutterBottom>
              Pagos Pendientes
            </Typography>
            <Typography component="p" variant="h4" sx={{ flexGrow: 1 }}>
              {formatCurrency(dashboardData.pendingPayments)}
            </Typography>
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <ReceiptIcon color="error" sx={{ mr: 1 }} />
              <Typography variant="body2" color="text.secondary">
                Por cobrar
              </Typography>
            </Box>
          </Paper>
        </Grid>
        
        <Grid item xs={12} sm={6} md={3}>
          <Paper sx={{ p: 2, display: 'flex', flexDirection: 'column', height: 140 }}>
            <Typography variant="h6" color="text.secondary" gutterBottom>
              Valor de Inventario
            </Typography>
            <Typography component="p" variant="h4" sx={{ flexGrow: 1 }}>
              {formatCurrency(dashboardData.inventory)}
            </Typography>
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <InventoryIcon color="info" sx={{ mr: 1 }} />
              <Typography variant="body2" color="text.secondary">
                Actual
              </Typography>
            </Box>
          </Paper>
        </Grid>
        
        <Grid item xs={12} sm={6} md={3}>
          <Paper sx={{ p: 2, display: 'flex', flexDirection: 'column', height: 140 }}>
            <Typography variant="h6" color="text.secondary" gutterBottom>
              Flujo de Efectivo
            </Typography>
            <Typography component="p" variant="h4" sx={{ flexGrow: 1 }}>
              {formatCurrency(dashboardData.cashFlow)}
            </Typography>
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <AccountBalanceWalletIcon color="success" sx={{ mr: 1 }} />
              <Typography variant="body2" color="text.secondary">
                Disponible
              </Typography>
            </Box>
          </Paper>
        </Grid>
      </Grid>
      
      {/* Module Navigation Cards */}
      <Typography variant="h5" gutterBottom sx={{ mb: 3 }}>
        Módulos de Gestión
      </Typography>
      
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={4}>
          <Card>
            <CardActionArea onClick={() => handleNavigate('control')}>
              <CardContent sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', p: 3 }}>
                <PointOfSaleIcon sx={{ fontSize: 60, color: 'primary.main', mb: 2 }} />
                <Typography variant="h6" component="div">
                  Control de Ventas
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', mt: 1 }}>
                  Gestiona tus ventas, clientes y facturas
                </Typography>
              </CardContent>
            </CardActionArea>
          </Card>
        </Grid>
        
        <Grid item xs={12} sm={6} md={4}>
          <Card>
            <CardActionArea onClick={() => handleNavigate('compras')}>
              <CardContent sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', p: 3 }}>
                <ShoppingCartIcon sx={{ fontSize: 60, color: 'secondary.main', mb: 2 }} />
                <Typography variant="h6" component="div">
                  Gestión de Compras
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', mt: 1 }}>
                  Administra proveedores y órdenes de compra
                </Typography>
              </CardContent>
            </CardActionArea>
          </Card>
        </Grid>
        
        <Grid item xs={12} sm={6} md={4}>
          <Card>
            <CardActionArea onClick={() => handleNavigate('inventario')}>
              <CardContent sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', p: 3 }}>
                <InventoryIcon sx={{ fontSize: 60, color: 'info.main', mb: 2 }} />
                <Typography variant="h6" component="div">
                  Inventario
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', mt: 1 }}>
                  Control de productos, stock y movimientos
                </Typography>
              </CardContent>
            </CardActionArea>
          </Card>
        </Grid>
        
        <Grid item xs={12} sm={6} md={4}>
          <Card>
            <CardActionArea onClick={() => handleNavigate('flujo-efectivo')}>
              <CardContent sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', p: 3 }}>
                <AccountBalanceWalletIcon sx={{ fontSize: 60, color: 'success.main', mb: 2 }} />
                <Typography variant="h6" component="div">
                  Flujo de Efectivo
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', mt: 1 }}>
                  Seguimiento de ingresos, gastos y proyecciones
                </Typography>
              </CardContent>
            </CardActionArea>
          </Card>
        </Grid>
        
        <Grid item xs={12} sm={6} md={4}>
          <Card>
            <CardActionArea onClick={() => handleNavigate('contabilidad')}>
              <CardContent sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', p: 3 }}>
                <ReceiptIcon sx={{ fontSize: 60, color: 'warning.main', mb: 2 }} />
                <Typography variant="h6" component="div">
                  Contabilidad Básica
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', mt: 1 }}>
                  Balance, estado de resultados e impuestos
                </Typography>
              </CardContent>
            </CardActionArea>
          </Card>
        </Grid>
      </Grid>
      
      {/* Recent Sales Table */}
      <Typography variant="h5" gutterBottom sx={{ mb: 3 }}>
        Ventas Recientes
      </Typography>
      
      <TableContainer component={Paper}>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>ID</TableCell>
              <TableCell>Fecha</TableCell>
              <TableCell>Cliente</TableCell>
              <TableCell align="right">Total</TableCell>
              <TableCell align="center">Estado</TableCell>
              <TableCell align="right">Acciones</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {recentSales.map((sale) => (
              <TableRow key={sale.id}>
                <TableCell>{sale.id}</TableCell>
                <TableCell>{formatDate(sale.date)}</TableCell>
                <TableCell>{sale.customer}</TableCell>
                <TableCell align="right">{formatCurrency(sale.total)}</TableCell>
                <TableCell align="center">
                  <Chip 
                    label={sale.status}
                    color={getStatusColor(sale.status)}
                    size="small"
                  />
                </TableCell>
                <TableCell align="right">
                  <Button size="small" color="primary">
                    Ver
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
      
      <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2 }}>
        <Button color="primary">
          Ver todas las ventas
        </Button>
      </Box>
    </Container>
  );
};

export default SalesPage;